class UserCancelled(Exception):
    pass


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def load_data() -> dict:
    compressed = base64.b85decode("".join(DATA_B85.split()).encode("ascii"))
    raw = zlib.decompress(compressed)
    actual = sha256_bytes(raw)
    if actual != DATA_JSON_SHA256:
        raise RuntimeError(
            "Integralność danych aplikacji jest naruszona: "
            f"{actual} != {DATA_JSON_SHA256}"
        )
    return json.loads(raw.decode("utf-8"))


def _refresh_prompt_identity(prompt: dict) -> None:
    raw = prompt["text"].encode("utf-8")
    prompt["bytes"] = len(raw)
    prompt["sha256"] = sha256_bytes(raw)


def _prior_handoff_name_for_embedded_step(variant: dict, step: dict) -> str | None:
    folder = str(step.get("folder", "")).upper()
    if int(step.get("order", 0)) <= 1:
        return None
    if "CANONICAL" in folder:
        return "F1_HANDOFF_BUNDLE.zip"
    if "PREVIOUS_PROMPT" in folder:
        return "POST_CANONICAL_HANDOFF_BUNDLE.zip" if variant.get("plus_pliki") else "F1_HANDOFF_BUNDLE.zip"
    if "PREVIOUS_REPORT" in folder:
        return "F2_HANDOFF_BUNDLE.zip"
    return None


def apply_runtime_patches(data: dict) -> dict:
    """Apply app-level orchestration/wrapper corrections deterministically.

    The compressed package is still verified against its original raw SHA before this
    transformation.  Every mutated prompt gets a freshly recomputed raw SHA-256 which
    is then carried by BDB_EXECUTION_CONTEXT/RUN_MANIFEST.
    """
    data["app_version"] = APP_VERSION

    # Repository specialization: Archive / main.  Keep the embedded package
    # byte-verified first, then retarget only repository/source-selection data.
    archive_repo_url = "https://github.com/eagleblastmusic-lgtm/Archive"
    archive_repo_clone_url = archive_repo_url + ".git"
    archive_repo_slug = "eagleblastmusic-lgtm/Archive"
    archive_ref = "refs/heads/main"
    archive_branch = "main"

    generator_item = data.get("capsule_generator")
    if isinstance(generator_item, dict):
        generator_raw = base64.b64decode(generator_item["data_b64"])
        generator_source = generator_raw.decode("utf-8")
        replacements = (
            ("eagleblastmusic-lgtm/benchmarki at\nrefs/heads/vnext",
             "eagleblastmusic-lgtm/Archive at\nrefs/heads/main"),
            ('REPO_URL = "https://github.com/eagleblastmusic-lgtm/benchmarki.git"',
             f'REPO_URL = "{archive_repo_clone_url}"'),
            ('REPO_SLUG = "eagleblastmusic-lgtm/benchmarki"',
             f'REPO_SLUG = "{archive_repo_slug}"'),
            ('REF = "refs/heads/vnext"', f'REF = "{archive_ref}"'),
            ('BRANCH = "vnext"', f'BRANCH = "{archive_branch}"'),
        )
        for old, new in replacements:
            if old not in generator_source:
                raise RuntimeError(f"Nie znaleziono oczekiwanego selektora repo w generatorze: {old}")
            generator_source = generator_source.replace(old, new)
        generator_raw = generator_source.encode("utf-8")
        generator_item["data_b64"] = base64.b64encode(generator_raw).decode("ascii")
        generator_item["bytes"] = len(generator_raw)
        generator_item["sha256"] = sha256_bytes(generator_raw)

    old_helper = ORIGINAL_MECHANICAL_HELPER_SHA256
    new_helper = MECHANICAL_HELPER_SHA256

    old_base_clause = (
        "For `FIRST-PASS` / `ETAP 1 / BASE`, fail closed on any attempt to execute or\n"
        "simulate canonical reveal, previous-prompt reveal, previous-report reveal,\n"
        "F2, previous-finding adjudication or report-relation phases. Source-native\n"
        "documents may be inspected only as current-source evidence/history exposure;\n"
        "they never become staged canonical, previous prompt or previous report.\n"
        "A BASE run containing F2 or predecessor adjudication is invalid and cannot\n"
        "claim `PROTOCOL_CONFORMANCE = COMPLETE`."
    )
    new_base_clause = (
        "For `FIRST-PASS` / `ETAP 1 / BASE`, staged reveal is phase-sensitive. Before\n"
        "a valid durable F1 exists and the exact pre-reveal F1 continuity gate PASSes,\n"
        "fail closed on every canonical reveal. In a dedicated post-F1 canonical\n"
        "reveal/finalization KROK, `CURRENT_CANONICAL_REQUIREMENTS` is expressly\n"
        "ALLOWED only after that exact continuity PASS and only through the deferred/\n"
        "attested FALLBACK transport contract in this wrapper. Previous-prompt reveal,\n"
        "previous-report reveal, F2, previous-finding adjudication and report-relation\n"
        "remain `NOT_APPLICABLE_AND_FORBIDDEN` for BASE. Source-native documents may be\n"
        "inspected only as current-source evidence/history exposure; they never become\n"
        "staged canonical, previous prompt or previous report. A BASE run containing F2\n"
        "or predecessor adjudication is invalid and cannot claim\n"
        "`PROTOCOL_CONFORMANCE = COMPLETE`."
    )

    for variant in data.get("variants", []):
        for step in variant.get("steps", []):
            reveal_handoff = _prior_handoff_name_for_embedded_step(variant, step) if variant.get("plus_pliki") else None
            for prompt_key in ("primary_prompt", "fallback_prompt"):
                prompt = step.get(prompt_key)
                if not prompt:
                    continue
                value = prompt["text"]
                value = value.replace(old_helper, new_helper)
                value = value.replace("https://github.com/eagleblastmusic-lgtm/benchmarki", archive_repo_url)
                value = value.replace("eagleblastmusic-lgtm/benchmarki", archive_repo_slug)
                value = value.replace("refs/heads/vnext", archive_ref)
                value = value.replace("`bdb-vnext`", "`main`")
                # Align durable ledger contract with the helper's true append-only JSONL mechanics.
                value = value.replace("AUDIT_LEDGER.json", "AUDIT_LEDGER.jsonl")
                if (
                    variant.get("audit_level") == "BASE"
                    and variant.get("plus_pliki")
                    and "CANONICAL" in str(step.get("folder", "")).upper()
                ):
                    value = value.replace(old_base_clause, new_base_clause)
                if reveal_handoff:
                    marker = f"LAUNCHER-ENFORCED PRIOR-HANDOFF REQUIREMENT — APP v{APP_VERSION} MANDATORY"
                    if marker not in value:
                        block = (
                            "\n\n" + marker + "\n\n"
                            f"For this +PLIKI reveal step, the exact prior handoff `{reveal_handoff}` MUST be\n"
                            "physically attached at message start. The launcher validates its ZIP integrity,\n"
                            "artifact hash manifest, exact VARIANT_ID/run identity, required checkpoint,\n"
                            "retained-ledger digest/raw-prefix continuity and frozen source identity before\n"
                            "preparing this message. Do not substitute chat-retained artifacts, a different\n"
                            "variant's final bundle, a reconstructed checkpoint, or a fresh source generation.\n"
                            "Reverify the attached handoff again before any staged semantic reveal.\n"
                        )
                        value = value.replace("\n\nEXECUTION-WRAPPER HARDENING — MANDATORY", block + "\n\nEXECUTION-WRAPPER HARDENING — MANDATORY", 1)
                prompt["text"] = value
                _refresh_prompt_identity(prompt)

            for instruction_key in ("primary_instruction", "fallback_instruction"):
                instruction = step.get(instruction_key)
                if not instruction:
                    continue
                instruction = instruction.replace("AUDIT_LEDGER.json", "AUDIT_LEDGER.jsonl")
                instruction = instruction.replace("https://github.com/eagleblastmusic-lgtm/benchmarki", archive_repo_url)
                instruction = instruction.replace("eagleblastmusic-lgtm/benchmarki", archive_repo_slug)
                instruction = instruction.replace("refs/heads/vnext", archive_ref)
                instruction = instruction.replace("`bdb-vnext`", "`main`")
                if reveal_handoff:
                    # Remove the unsafe "same conversation probably still has it" shortcut.
                    instruction = instruction.replace(
                        "F1_HANDOFF_BUNDLE.zip — tylko gdy rozmowa nie zachowała zweryfikowanych artefaktów KROK 1",
                        "F1_HANDOFF_BUNDLE.zip — OBOWIĄZKOWO; aplikacja lokalnie weryfikuje dokładny F1 przed przygotowaniem KROKU",
                    )
                    instruction = instruction.replace(
                        "odpowiedni oryginalny handoff (F1/F2/post-canonical), jeśli rozmowa go nie zachowała",
                        f"`{reveal_handoff}` — OBOWIĄZKOWO; dokładny oryginalny handoff lokalnie zweryfikowany przez aplikację",
                    )
                    mandatory_note = (
                        f"\n\n## OBOWIĄZKOWY POPRZEDNI HANDOFF — APP v{APP_VERSION}\n\n"
                        f"Dołącz `{reveal_handoff}` zawsze, nawet jeżeli rozmowa wygląda na zachowującą poprzednie artefakty. "
                        "Aplikacja odrzuca zły wariant, brak checkpointu, niespójny RUN/AUDIT identity, błędne hashe, "
                        "niespójny ledger-prefix lub inną frozen source identity zanim staged payload zostanie odblokowany.\n"
                    )
                    if f"## OBOWIĄZKOWY POPRZEDNI HANDOFF — APP v{APP_VERSION}" not in instruction:
                        instruction += mandatory_note
                step[instruction_key] = instruction

    # Previous-prompt bundles are derived lineage artifacts.  Build them in
    # predecessor order and then propagate their FINAL byte identity back into every
    # consumer prompt/instruction that preregisters or reveals that bundle.  This is
    # intentionally topological: changing an ITERACJA 1 prompt changes the exact
    # predecessor-prompt bundle consumed by ITERACJA 2.
    variant_map = {item.get("variant_id"): item for item in data.get("variants", [])}

    def lineage_depth(variant: dict) -> int:
        depth = 0
        seen: set[str] = set()
        parent_id = variant.get("direct_predecessor_variant_id")
        while parent_id:
            if parent_id in seen:
                raise RuntimeError(f"Cykl direct-predecessor lineage przy {variant.get('variant_id')}: {parent_id}")
            seen.add(parent_id)
            parent = variant_map.get(parent_id)
            if parent is None:
                raise RuntimeError(f"Brak direct predecessor {parent_id} dla {variant.get('variant_id')}")
            depth += 1
            parent_id = parent.get("direct_predecessor_variant_id")
        return depth

    def rewrite_bundle_sha_reference(text: str, bundle_name: str, bundle_sha256: str) -> str:
        if bundle_name not in text:
            return text
        hex64 = r"[0-9a-fA-F]{64}"
        escaped_name = re.escape(bundle_name)
        patterns = (
            (rf"(Expected bundle SHA-256:\s*`){hex64}(`)", rf"\g<1>{bundle_sha256}\g<2>"),
            (rf"(Required previous-prompt bundle SHA-256:\s*`){hex64}(`)", rf"\g<1>{bundle_sha256}\g<2>"),
            (rf"(filename:\s*`{escaped_name}`;\s*required_sha256:\s*`){hex64}(`)", rf"\g<1>{bundle_sha256}\g<2>"),
            (rf"('filename':\s*'{escaped_name}',\s*'sha256':\s*'){hex64}(')", rf"\g<1>{bundle_sha256}\g<2>"),
        )
        rewritten = text
        for pattern, replacement in patterns:
            rewritten = re.sub(pattern, replacement, rewritten)
        return rewritten

    consumers = [item for item in data.get("variants", []) if item.get("direct_predecessor_variant_id")]
    consumers.sort(key=lambda item: (lineage_depth(item), str(item.get("variant_id", ""))))

    for consumer in consumers:
        parent_id = consumer["direct_predecessor_variant_id"]
        parent = variant_map[parent_id]
        parent_prompts = [
            step["primary_prompt"]
            for step in sorted(parent.get("steps", []), key=lambda row: row.get("order", 0))
            if step.get("primary_prompt")
        ]
        bundle_items = [
            bundle
            for step in consumer.get("steps", [])
            for bundle in step.get("previous_prompt_bundles", [])
        ]
        by_name: dict[str, list[dict]] = {}
        for bundle in bundle_items:
            by_name.setdefault(bundle["name"], []).append(bundle)

        for bundle_name, same_name_items in sorted(by_name.items()):
            prompt_rows = [
                {
                    "filename": prompt["name"],
                    "sha256": prompt["sha256"],
                    "size_bytes": len(prompt["text"].encode("utf-8")),
                }
                for prompt in parent_prompts
            ]
            manifest = {
                "consumer_variant_id": consumer["variant_id"],
                "direct_predecessor_only": True,
                "expected_predecessor_variant_id": parent_id,
                "prompt_files": prompt_rows,
                "schema": "BDB_PA_V5_2_PREVIOUS_PROMPT_BUNDLE_V1",
            }
            manifest_raw = (json.dumps(manifest, ensure_ascii=False, indent=2, sort_keys=True) + "\n").encode("utf-8")
            out = io.BytesIO()
            with zipfile.ZipFile(out, "w") as archive:
                def write_deterministic(name: str, raw: bytes) -> None:
                    info = zipfile.ZipInfo(name, date_time=(1980, 1, 1, 0, 0, 0))
                    info.compress_type = zipfile.ZIP_DEFLATED
                    info.external_attr = 0o100644 << 16
                    archive.writestr(info, raw)
                write_deterministic("PREVIOUS_PROMPTS_MANIFEST.json", manifest_raw)
                for prompt in sorted(parent_prompts, key=lambda item: item["name"]):
                    write_deterministic(prompt["name"], prompt["text"].encode("utf-8"))
            raw_bundle = out.getvalue()
            final_sha = sha256_bytes(raw_bundle)
            for bundle in same_name_items:
                bundle["data_b64"] = base64.b64encode(raw_bundle).decode("ascii")
                bundle["bytes"] = len(raw_bundle)
                bundle["sha256"] = final_sha

            # The consumer's own prompts may have preregistered one generation of the
            # bundle and the reveal prompt another.  Normalize every declared identity
            # to the exact bytes just built, then refresh prompt identities.  Doing this
            # before the next lineage depth ensures descendants bundle the corrected
            # prompt bytes, not stale-hash prompt bytes.
            for step in consumer.get("steps", []):
                for prompt_key in ("primary_prompt", "fallback_prompt"):
                    prompt = step.get(prompt_key)
                    if not prompt:
                        continue
                    rewritten = rewrite_bundle_sha_reference(prompt["text"], bundle_name, final_sha)
                    if rewritten != prompt["text"]:
                        prompt["text"] = rewritten
                        _refresh_prompt_identity(prompt)
                for instruction_key in ("primary_instruction", "fallback_instruction"):
                    instruction = step.get(instruction_key)
                    if instruction:
                        step[instruction_key] = rewrite_bundle_sha_reference(instruction, bundle_name, final_sha)
    return data


DATA = apply_runtime_patches(load_data())


def mechanical_helper_bytes() -> bytes:
    compressed = base64.b85decode("".join(MECHANICAL_HELPER_B85.split()).encode("ascii"))
    raw = zlib.decompress(compressed)
    original_actual = sha256_bytes(raw)
    if original_actual != ORIGINAL_MECHANICAL_HELPER_SHA256:
        raise RuntimeError(
            "Integralność bazowego helpera mechanicznego jest naruszona: "
            f"{original_actual} != {ORIGINAL_MECHANICAL_HELPER_SHA256}"
        )
    source = raw.decode("utf-8")
    # 1.4.2: argparse subparser identity may not share dest='command' with
    # record-event's optional --command payload field.
    source = source.replace('sub = parser.add_subparsers(dest="command")',
                            'sub = parser.add_subparsers(dest="subcommand")')
    source = source.replace('elif args.command == "verify-capsule":',
                            'elif args.subcommand == "verify-capsule":')
    source = source.replace('elif args.command == "verify-handoff":',
                            'elif args.subcommand == "verify-handoff":')
    source = source.replace('elif args.command == "finalize-package":',
                            'elif args.subcommand == "finalize-package":')
    source = source.replace('elif args.command == "record-event":',
                            'elif args.subcommand == "record-event":')
    patched = source.encode("utf-8")
    actual = sha256_bytes(patched)
    if actual != MECHANICAL_HELPER_SHA256:
        raise RuntimeError(
            "Integralność poprawionego helpera mechanicznego jest naruszona: "
            f"{actual} != {MECHANICAL_HELPER_SHA256}"
        )
    return patched


def build_sol_defensive_launcher(variant: dict, step: dict, fallback: bool, wrapper_filename: str) -> str:
    mode = "FALLBACK" if fallback else "PRIMARY"
    return textwrap.dedent(
        f"""\
        START THIS AUDIT STEP NOW. Do not ask the user what to do with the
        attachments. Execute the authorized defensive, read-only software quality
        assurance review described in the attached documents and proceed
        autonomously until this step's required STOP or final delivery gate.

        AUTHORIZATION AND SCOPE
        - I own or control the supplied public benchmark repository and authorize analysis of the supplied source generation.
        - Limit the work to source correctness, state and recovery behavior, evidence/test quality, provenance, and release reliability.
        - Read-only source acquisition from the explicitly named public benchmark
          GitHub repository is authorized when the attached wrapper selects Route
          A, B, or C. Do not write to GitHub or interact with unrelated third-party
          systems.
        - Do not perform destructive or external state-changing actions.
        - If an operation is unavailable or cannot be performed safely, mark that evidence edge BLOCKED and continue only with safe, permitted analysis.
        - If a valid request-bound Route-D capsule is attached, its acquisition
          event fixes this logical source generation. Do not replace it with a
          later live branch tip; any later read is drift observation only.
        - When recording a command result, capture its real exit code immediately.
          Never use `command || true; rc=$?`, because that records the recovery
          command's success instead of the audited command's result. A timeout,
          collection error, partial run, or skipped scope is not a clean PASS.

        GOVERNING_PROTOCOL = PA v5.2
        EXECUTION_WRAPPER_RELEASE = {DATA['wrapper_release']}
        VARIANT_ID = {variant['variant_id']}
        KROK = {step['order']}
        DELIVERY_MODE = {mode}

        Read and follow:
        1. attached `PA v5.2.md` as the frozen governing protocol;
        2. attached `{wrapper_filename}` as the complete execution-wrapper instructions for this exact step;
        3. attached `BDB_EXECUTION_CONTEXT.json` as the fail-closed machine
           identity and phase-permission record for this exact variant/KROK/mode;
        4. attached `BDB_AUDIT_MECHANICAL_HELPER.py` for mechanical-only
           capsule/handoff/hash/ZIP work; its expected raw SHA-256 is
           `{MECHANICAL_HELPER_SHA256}`;
        5. only the additional files physically attached for this step.

        Preserve all physical reveal gates, source-identity requirements, durable checkpoint rules, and evidence limits. Do not infer permission to retrieve absent staged material. Do not claim technical completion unless the required evidence and artifact gates actually pass.
        """
    )


def build_sol_framed_wrapper(prompt_text: str, prompt_sha256: str, prompt_name: str) -> bytes:
    header = textwrap.dedent(
        f"""\
        # AUTHORIZED DEFENSIVE SOFTWARE QUALITY REVIEW

        This document governs a read-only review of a public benchmark repository
        owned or controlled by the requester. It authorizes source-quality analysis
        only. It does not authorize third-party interaction or destructive/external
        actions. Any unavailable or unsafe evidence edge must be recorded as BLOCKED.

        ORIGINAL_WRAPPER_PROMPT_FILENAME = {prompt_name}
        ORIGINAL_WRAPPER_PROMPT_SHA256 = {prompt_sha256}

        # BEGIN COMPLETE EXECUTION-WRAPPER INSTRUCTIONS

        """
    )
    return (header + prompt_text).encode("utf-8")


def build_sol_input_registration(variant: dict, step: dict, attachment_names: list[str]) -> str:
    listed = "\n".join(f"        - `{name}`" for name in attachment_names)
    return textwrap.dedent(
        f"""\
        REGISTER INPUTS FOR A PENDING AUTHORIZED READ-ONLY SOFTWARE QUALITY REVIEW.
        DO NOT START THE AUDIT YET AND DO NOT ANALYZE SOURCE SEMANTICS IN THIS MESSAGE.

        VARIANT_ID = {variant['variant_id']}
        KROK = {step['order']}

        Confirm only that these attached files are physically available in this
        conversation:
        {listed}

        Reply immediately and only with:

        INPUTS_REGISTERED = YES | NO
        PA_V5_2_PRESENT = YES | NO
        EXECUTION_WRAPPER_PRESENT = YES | NO
        EXECUTION_CONTEXT_PRESENT = YES | NO
        SOURCE_CAPSULE_PRESENT = YES | NO | NOT_APPLICABLE
        READY_FOR_EXPLICIT_START_MESSAGE = YES | NO

        Do not mint AUDIT_ATTEMPT_ID, perform source acquisition, open canonical
        content, or execute PA v5.2 until the next explicit START message in this
        same conversation.
        """
    )


def clear_screen() -> None:
    os.system("cls" if os.name == "nt" else "clear")


def print_banner() -> None:
    print("=" * 72)
    print("BDB AUDIT ASSISTANT")
    print(f"Aplikacja: v{APP_VERSION}")
    print(f"Pakiet wrapperów: {DATA['wrapper_release']}")
    print(f"Protokół: {DATA['governing_protocol']}")
    print("=" * 72)


def pause(message: str = "Naciśnij ENTER, aby kontynuować...") -> None:
    try:
        input(message)
    except EOFError:
        pass


def choose(title: str, options: list[tuple[str, object]], allow_back: bool = True):
    while True:
        print(f"\n{title}")
        for index, (label, _) in enumerate(options, 1):
            print(f"  {index}. {label}")
        if allow_back:
            print("  0. Wróć")
        raw = input("Wybór: ").strip()
        if allow_back and raw == "0":
            raise UserCancelled()
        if raw.isdigit() and 1 <= int(raw) <= len(options):
            return options[int(raw) - 1][1]
        print("Nieprawidłowy wybór.")


def yes_no(question: str, default: bool = True) -> bool:
    suffix = "[T/n]" if default else "[t/N]"
    while True:
        answer = input(f"{question} {suffix}: ").strip().lower()
        if not answer:
            return default
        if answer in {"t", "tak", "y", "yes"}:
            return True
        if answer in {"n", "nie", "no"}:
            return False
        print("Wpisz T albo N.")


def strip_user_quotes(value: str) -> str:
    value = value.strip()
    while len(value) >= 2 and value[0] == value[-1] and value[0] in {'"', "'"}:
        value = value[1:-1].strip()
    return value


def normalize_user_path(value: str) -> str:
    """Accept ordinary paths, quoted drag-and-drop paths, and file:/// URLs."""
    value = strip_user_quotes(value)
    if not value.lower().startswith("file:"):
        return value
    parsed = urlparse(value)
    if parsed.scheme.lower() != "file":
        return value
    path = unquote(parsed.path)
    if parsed.netloc and parsed.netloc.lower() not in {"", "localhost"}:
        path = f"//{parsed.netloc}{path}"
    if os.name == "nt" and re.match(r"^/[A-Za-z]:/", path):
        path = path[1:]
    return path.replace("/", os.sep) if os.name == "nt" else path


def select_file(title: str, zip_only: bool = False) -> Path:
    selected = ""
    try:
        import tkinter as tk
        from tkinter import filedialog

        root = tk.Tk()
        root.withdraw()
        try:
            root.attributes("-topmost", True)
        except Exception:
            pass
        filetypes = [("Pliki ZIP", "*.zip"), ("Wszystkie pliki", "*.*")] if zip_only else [("Wszystkie pliki", "*.*")]
        selected = filedialog.askopenfilename(title=title, filetypes=filetypes)
        root.destroy()
    except Exception:
        selected = ""
    if not selected:
        print(f"\n{title}")
        selected = strip_user_quotes(input("Wklej pełną ścieżkę (może być w cudzysłowie): "))
    path = Path(os.path.expandvars(os.path.expanduser(normalize_user_path(selected))))
    if not path.is_file():
        raise FileNotFoundError(f"Nie znaleziono pliku: {path}")
    if zip_only and path.suffix.lower() != ".zip":
        raise ValueError(f"To nie jest plik ZIP: {path}")
    return path.resolve()


def select_directory(title: str) -> Path | None:
    selected = ""
    try:
        import tkinter as tk
        from tkinter import filedialog

        root = tk.Tk()
        root.withdraw()
        try:
            root.attributes("-topmost", True)
        except Exception:
            pass
        selected = filedialog.askdirectory(title=title)
        root.destroy()
    except Exception:
        selected = ""
    if not selected:
        raw = strip_user_quotes(input(f"{title}\nŚcieżka (ENTER = pomiń): "))
        if not raw:
            return None
        selected = raw
    path = Path(os.path.expandvars(os.path.expanduser(normalize_user_path(selected))))
    if not path.is_dir():
        raise FileNotFoundError(f"Nie znaleziono folderu: {path}")
    return path.resolve()


def copy_to_clipboard_windows(text: str) -> None:
    if os.name != "nt":
        raise RuntimeError("WinAPI clipboard jest dostępny tylko na Windows")
    user32 = ctypes.windll.user32
    kernel32 = ctypes.windll.kernel32
    GMEM_MOVEABLE = 0x0002
    CF_UNICODETEXT = 13
    kernel32.GlobalAlloc.argtypes = [wintypes.UINT, ctypes.c_size_t]
    kernel32.GlobalAlloc.restype = wintypes.HGLOBAL
    kernel32.GlobalLock.argtypes = [wintypes.HGLOBAL]
    kernel32.GlobalLock.restype = ctypes.c_void_p
    kernel32.GlobalUnlock.argtypes = [wintypes.HGLOBAL]
    user32.SetClipboardData.argtypes = [wintypes.UINT, wintypes.HANDLE]
    user32.SetClipboardData.restype = wintypes.HANDLE
    payload = (text + "\0").encode("utf-16-le")
    handle = kernel32.GlobalAlloc(GMEM_MOVEABLE, len(payload))
    if not handle:
        raise RuntimeError("GlobalAlloc nie powiódł się")
    pointer = kernel32.GlobalLock(handle)
    if not pointer:
        raise RuntimeError("GlobalLock nie powiódł się")
    ctypes.memmove(pointer, payload, len(payload))
    kernel32.GlobalUnlock(handle)
    if not user32.OpenClipboard(None):
        raise RuntimeError("Nie można otworzyć schowka")
    try:
        user32.EmptyClipboard()
        if not user32.SetClipboardData(CF_UNICODETEXT, handle):
            raise RuntimeError("SetClipboardData nie powiódł się")
        handle = None
    finally:
        user32.CloseClipboard()


def copy_to_clipboard(text: str) -> bool:
    try:
        copy_to_clipboard_windows(text)
        return True
    except Exception:
        pass
    try:
        import tkinter as tk

        root = tk.Tk()
        root.withdraw()
        root.clipboard_clear()
        root.clipboard_append(text)
        root.update()
        root.destroy()
        return True
    except Exception:
        return False


def open_folder(path: Path) -> None:
    try:
        if os.name == "nt":
            os.startfile(str(path))  # type: ignore[attr-defined]
        elif sys.platform == "darwin":
            subprocess.Popen(["open", str(path)])
        else:
            subprocess.Popen(["xdg-open", str(path)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception:
        pass


def downloads_root() -> Path:
    preferred = Path.home() / "Downloads"
    base = preferred if preferred.is_dir() else Path.cwd()
    root = base / "BDB_AUDIT_ASSISTANT"
    root.mkdir(parents=True, exist_ok=True)
    return root


def save_last_clipboard_message(text: str, label: str) -> Path:
    root = downloads_root()
    path = root / "OSTATNIA_WIADOMOSC_DO_WKLEJENIA.txt"
    path.write_text(text, encoding="utf-8", newline="\n")
    (root / "OSTATNIA_WIADOMOSC_INFO.txt").write_text(
        f"APP_VERSION={APP_VERSION}\nLABEL={label}\n"
        f"SAVED_AT={dt.datetime.now().astimezone().isoformat()}\n",
        encoding="utf-8",
        newline="\n",
    )
    return path


def recopy_last_message() -> bool:
    path = downloads_root() / "OSTATNIA_WIADOMOSC_DO_WKLEJENIA.txt"
    if not path.is_file():
        print("\nNie ma jeszcze przygotowanej wiadomości.")
        return False
    text = path.read_text(encoding="utf-8")
    if not text.strip():
        print("\nOstatnia wiadomość jest pusta.")
        return False
    ok = copy_to_clipboard(text)
    print("\n" + ("Skopiowano ostatnią wiadomość do schowka." if ok else f"Nie udało się użyć schowka. Otwórz: {path}"))
    print("Pierwsza linia:", text.splitlines()[0])
    return ok


def unique_ready_dir(variant_id: str, step_order: int, fallback: bool) -> Path:
    stamp = dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    suffix = "_FALLBACK" if fallback else "_PRIMARY"
    base = downloads_root() / f"{stamp}_{variant_id}_KROK_{step_order}{suffix}"
    candidate = base
    counter = 2
    while candidate.exists():
        candidate = Path(str(base) + f"_{counter}")
        counter += 1
    candidate.mkdir(parents=True)
    (candidate / "ZALACZNIKI_TERAZ").mkdir()
    return candidate


def embedded_bytes(item: dict) -> bytes:
    raw = base64.b64decode(item["data_b64"])
    actual = sha256_bytes(raw)
    if actual != item["sha256"]:
        raise RuntimeError(f"Błąd integralności wbudowanego pliku {item['name']}")
    return raw


def write_embedded(item: dict, destination: Path) -> None:
    destination.write_bytes(embedded_bytes(item))
    if sha256_file(destination) != item["sha256"]:
        raise RuntimeError(f"Readback nie przeszedł dla {destination}")


def copy_dynamic(source: Path, destination_dir: Path, target_name: str | None = None) -> Path:
    target = destination_dir / (target_name or source.name)
    shutil.copy2(source, target)
    if sha256_file(source) != sha256_file(target):
        raise RuntimeError(f"Kopiowanie nie zachowało bajtów: {source}")
    return target


def find_variant(stage: str, tool: str, plus: bool) -> dict:
    matches = [
        item for item in DATA["variants"]
        if item["audit_level"] == stage and item["tool"] == tool and bool(item["plus_pliki"]) == plus
    ]
    if len(matches) != 1:
        raise RuntimeError(f"Nie znaleziono jednoznacznego wariantu: {stage}/{tool}/{plus}")
    return matches[0]


